import { describe, expect, test } from "vitest";
import { convexTest } from "convex-test";
import { api, internal } from "./_generated/api";
import schema from "./schema";
import { validateImage } from "./lib/images";
import { IMAGE_MAX_BYTES, IMAGE_USER_QUOTA, IMAGE_TOTAL_QUOTA } from "../lib/image-limits";
import { readFileSync } from "node:fs";

const modules = import.meta.glob("./**/*.ts");
// A real, tiny JPEG fixture generated by the browser-independent image tooling.
const photo = () => new Uint8Array(readFileSync(new URL('../tests/fixtures/photo.jpg', import.meta.url))).buffer;
async function fixture() {
  const t = convexTest(schema, modules);
  const owner = t.withIdentity({ subject: "owner" });
  const friend = t.withIdentity({ subject: "friend" });
  const ownerId = await owner.mutation(api.profiles.ensure, {});
  await friend.mutation(api.profiles.ensure, {});
  const listId = await owner.mutation(api.lists.create, { title: "Foto", description: "", cover: "sand" });
  const giftId = await owner.mutation(api.gifts.create, { listId, title: "Regalo", description: "", currency: "EUR", category: "other", priority: "normal", locations: [] });
  return { t, owner, friend, ownerId, listId, giftId };
}

describe("Immagini con limiti di storage", () => {
  test("rifiuta file grandi, formati contraffatti e dimensioni eccessive", () => {
    expect(() => validateImage(new ArrayBuffer(IMAGE_MAX_BYTES + 1))).toThrow("250 KB");
    expect(() => validateImage(new TextEncoder().encode('<svg/>').buffer)).toThrow("non valida");
    const bytes = new Uint8Array(photo());
    for (let i=0; i<bytes.length-9; i++) if(bytes[i]===255 && bytes[i+1]===192) {bytes[i+7]=255; bytes[i+8]=255; break;}
    expect(() => validateImage(bytes.buffer)).toThrow("1200 pixel");
  });
  test("carica, sostituisce e rimuove senza lasciare vecchi file", async () => {
    const { t, owner, listId } = await fixture();
    await owner.action(api.images.upload, { listId, bytes: photo() });
    const first = (await owner.query(api.lists.getOwnerDetail, { listId })).list;
    expect(first.imageUrl).toBeTruthy();
    expect((await owner.query(api.lists.getOwned, {}))[0].imageUrl).toBe(first.imageUrl);
    await owner.action(api.images.upload, { listId, bytes: photo() });
    expect(await t.run(ctx => ctx.storage.get(first.imageId!))).toBeNull();
    expect((await t.run(ctx => ctx.db.query("imageUsage").collect())).map(x=>x.bytes)).toEqual([photo().byteLength,photo().byteLength]);
    await owner.mutation(api.images.remove, { listId });
    expect((await owner.query(api.lists.getOwnerDetail, { listId })).list.imageUrl).toBeNull();
    expect((await t.run(ctx => ctx.db.query("imageUsage").collect())).every(x=>x.bytes===0)).toBe(true);
    expect(await t.run(ctx => ctx.db.system.query("_storage").collect())).toHaveLength(0);
  });
  test("autorizzazione, lista archiviata e regalo appartenente ad altra lista", async () => {
    const { t, owner, friend, listId, giftId } = await fixture();
    await expect(friend.action(api.images.upload, { listId, bytes: photo() })).rejects.toThrow();
    await expect(t.action(api.images.upload, { listId, bytes: photo() })).rejects.toThrow();
    await expect(friend.mutation(api.images.remove, { listId })).rejects.toThrow();
    const other = await owner.mutation(api.lists.create, { title: "Altro", description: "", cover: "plum" });
    await expect(owner.action(api.images.upload, { listId: other, giftId, bytes: photo() })).rejects.toThrow();
    await owner.mutation(api.lists.setArchived, { listId, archived: true });
    await expect(owner.action(api.images.upload, { listId, bytes: photo() })).rejects.toThrow("Riattiva");
    expect(await t.run(ctx => ctx.db.system.query("_storage").collect())).toHaveLength(0);
  });
  test("quota account, quota globale e pulizia dopo rifiuto", async () => {
    const { t, owner, listId } = await fixture();
    const ownerDoc = await t.run(ctx => ctx.db.query("users").withIndex("by_clerkId", q=>q.eq("clerkId","owner")).unique());
    await t.run(ctx=>ctx.db.insert("imageUsage", {key:String(ownerDoc!._id), bytes:IMAGE_USER_QUOTA}));
    await expect(owner.action(api.images.upload, { listId, bytes: photo() })).rejects.toThrow("10 MB");
    await t.run(async ctx=>{ const usage=await ctx.db.query("imageUsage").first(); await ctx.db.patch(usage!._id,{bytes:0}); await ctx.db.insert("imageUsage",{key:"global",bytes:IMAGE_TOTAL_QUOTA}); });
    await expect(owner.action(api.images.upload, { listId, bytes: photo() })).rejects.toThrow("esaurito");
    expect(await t.run(ctx => ctx.db.system.query("_storage").collect())).toHaveLength(0);
  });
  test("limite giornaliero applicato prima di memorizzare il file", async () => {
    const { t, owner, listId } = await fixture();
    const user = await t.run(ctx => ctx.db.query("users").withIndex("by_clerkId", q=>q.eq("clerkId","owner")).unique());
    await t.run(ctx=>ctx.db.insert("imageUploadQuota",{userId:user!._id,windowStart:Date.now(),count:30}));
    await expect(owner.action(api.images.upload,{listId,bytes:photo()})).rejects.toThrow("domani");
    expect(await t.run(ctx=>ctx.db.system.query("_storage").collect())).toHaveLength(0);
  });
  test("amici e ospiti vedono le foto, la rimozione del regalo libera spazio", async () => {
    const { t, owner, friend, listId, giftId } = await fixture();
    await owner.action(api.images.upload, { listId, bytes: photo() });
    await owner.action(api.images.upload, { listId, giftId, bytes: photo() });
    const {token}=await owner.action(api.inviteLinks.create,{listId});
    await friend.mutation(api.invites.join,{token});
    const view=await friend.query(api.lists.getParticipantDetail,{listId});
    expect(view.imageUrl).toBeTruthy(); expect(view.gifts[0].imageUrl).toBeTruthy();
    const guest=await t.action(api.guestAccess.create,{token});
    const guestView=await t.query(api.guests.getDetail,{token,secret:guest.secret});
    expect(guestView.access).toBe("active");
    if(guestView.access==='active') expect(guestView.detail.gifts[0].imageUrl).toBeTruthy();
    await owner.mutation(api.gifts.remove,{giftId,expectedVersion:1});
    expect(await t.run(ctx=>ctx.db.system.query("_storage").collect())).toHaveLength(1);
    await owner.mutation(api.images.remove,{listId});
    expect(await t.run(ctx=>ctx.db.system.query("_storage").collect())).toHaveLength(0);
  });
  test("eliminare l’account elimina foto e contatori", async () => {
    const { t, owner, listId, giftId } = await fixture();
    await owner.action(api.images.upload,{listId,bytes:photo()});
    await owner.action(api.images.upload,{listId,giftId,bytes:photo()});
    await t.mutation(internal.clerk.deleteUser,{clerkId:"owner",eventAt:Date.now()});
    await t.finishAllScheduledFunctions(()=>{});
    expect(await t.run(ctx=>ctx.db.system.query("_storage").collect())).toHaveLength(0);
    expect((await t.run(ctx=>ctx.db.query("imageUsage").collect())).every(x=>x.bytes===0)).toBe(true);
  });
});
